1	<!doctype html>
2	<html><head><meta charset="utf-8"><title>Rainbow screen</title>
3	<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
4	<style>
5	html,body{margin:0;background:#1a0630;overflow:hidden;font-family:system-ui,-apple-system,sans-serif}canvas{display:block}
6	#hud{position:fixed;left:0;right:0;top:8px;display:flex;flex-direction:column;align-items:center;gap:7px;pointer-events:none}
7	.bar{display:flex;gap:26px;align-items:center;background:linear-gradient(#7b2bbf,#4a1386);border:2px solid #d9a7ff;border-radius:30px;padding:5px 20px;color:#fff;font-weight:800;font-size:21px;box-shadow:0 2px 8px #0006}
8	.title{background:#5a1aa0e0;border:2px solid #f2c14e;border-radius:20px;padding:4px 16px;color:#fff;font-weight:800;font-style:italic;font-size:16px;letter-spacing:.4px}
9	.pill{display:inline-flex;align-items:center;gap:6px}.plus{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:#7c3aed;border:2px solid #e9d5ff;font-size:16px;line-height:1}
10	#pause{position:fixed;top:8px;right:10px;width:46px;height:46px;border-radius:50%;border:3px solid #f2c14e;background:linear-gradient(#8b3fd9,#4a1386);color:#fff;font-weight:900;font-size:18px;pointer-events:auto}
11	#pausedLay{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:#1a063088;color:#fff;font-size:30px;font-weight:900}
12	#load{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:20px;background:#2a0b4a}
13	</style>
14	<script type="importmap">{"imports":{"three":"./node_modules/three/build/three.module.js","three/addons/":"./node_modules/three/examples/jsm/"}}</script>
15	</head><body>
16	<div id="hud"><div class="bar"><span class="pill">&#10084;&#65039; 5/5 <span class="plus">+</span></span><span class="pill"><span id="coins">&#129689; 0</span></span></div>
17	<div class="title" id="title"></div></div>
18	<button id="pause" data-noswipe aria-label="pause">&#10074;&#10074;</button><div id="pausedLay">Paused</div><div id="load">Building the washer&hellip;</div>
19	<script type="module">
20	// ======================================================================================================================================
21	// Rainbow SCREEN KIT game page (round 43) - one page for every playable screen built with tools/screenkit: the screen's own fitted
22	// layout (layout.json, from screens/NN/fitNN.py) + its Blender scenery (scene.glb, tools/screenkit/blender_kit.py). At load, the screen's
23	// approved picture(s) are BAKED once onto the meshes from the camera(s) fitted to them (depth-tested, masked where the game draws Benny /
24	// coins / HUD / bubbles itself, clean plate inside the masks), exactly the proven Bubble Dash method (tools/reflock/section.html, which
25	// stays untouched). Plain perspective camera; nothing follows the camera; no projection, no picture planes, no screen overlays.
26	// Shared game code: Benny 31 (paddling shader), tools/kit05/controls.js swipes, swimfx.js, the coin / splash textures.
