CACHE = os.environ.get('RAINBOW_BUILD_CACHE', os.path.expanduser('~/.cache/rainbow-build'))
MODELS = os.environ.get('RAINBOW_MODELS', os.path.expanduser('~/.cache/rainbow-models'))
NODE_MODULES = '/tmp/rainbow_r34/node_modules'


# ----------------------------------------------------------------------------------------------------------- hashing + cache
def h_bytes(*parts):
    h = hashlib.sha256()
