export const dataTex = (THREE, px, w, h) => { const t = new THREE.DataTexture(px, w, h); t.colorSpace = THREE.NoColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.generateMipmaps = true;
