const { chromium } = require('playwright'); const { spawn } = require('child_process');
(async () => { const port = 9955; const srv = spawn('python3', ['-m', 'http.server', '--bind', '127.0.0.1', String(port)], { cwd: process.argv[2], stdio: 'ignore' }); await new Promise((r) => setTimeout(r, 1000));
  const b = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] }); const p = await (await b.newContext({ viewport: { width: 412, height: 915 }, isMobile: true, hasTouch: true })).newPage();
  const errs = []; p.on('pageerror', (e) => errs.push(e.message)); const t = Date.now();
  await p.goto(`http://127.0.0.1:${port}/world/index.html`); await p.waitForFunction(() => window.ready === true, null, { timeout: 300000 });
  const btns = await p.evaluate(() => [...document.querySelectorAll('button')].map((b) => b.textContent)); await p.screenshot({ path: process.argv[3] });
  await p.tap('text=Start 05'); for (let i = 0; i < 40; i++) await p.waitForTimeout(100); const s = await p.evaluate(() => window.state().s);
  console.log(JSON.stringify({ load_s: (Date.now() - t) / 1000, buttons: btns, s_after_start05: s, errors: errs.slice(0, 5) })); await b.close(); srv.kill(); })();
EOF
NODE_PATH=$(npm root -g) node $S/apptest.cjs $PWD/dist qa/kit45/APP_world_start_screen.png 2>&1 | tail -2

